    AlarmNotification = apps.get_model("alarms", "AlarmNotification")

    for row in AlarmNotification.objects.filter(channel=TELEGRAM).iterator(chunk_size=BATCH_SIZE):
        Alarm.objects.filter(id=row.alarm_id).update(notified_at=row.raised_at, notified_clear_at=row.cleared_at)


